--- index.html
+++ index.html
@@ -20,6 +20,34 @@
 <div class="overlay" id="intro"><section class="panel"><div class="kicker">The return · 1990s inspired fiction</div><h1>THE WAY<br>BACK <em>HOME.</em></h1><p>Walk the mountain paths, restore the valley's signal beacons, and guide your team toward the old village. A quiet journey of courage, homecoming, and hope.</p><div class="objectives"><div><span class="objective-dot">1</span> Restore three valley beacons</div><div><span class="objective-dot">2</span> Reach the hilltop village</div></div><button class="startbtn" id="start">Begin the journey <span>→</span></button><div class="meta"><span>Touch controls ready</span> Non-violent exploration</div></section></div>
 <div class="overlay hidden" id="ending"><section class="panel"><div class="kicker">The valley remembers</div><h1>HOME,<br><em>AGAIN.</em></h1><p>The beacon shines across the valley. The path home is open, and the mountain carries the signal onward.</p><button class="startbtn" id="again">Walk the valley again ↻</button><div class="meta"><span>Journey complete</span> Thank you for playing</div></section></div>
 <script type="module">
 import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
-</script>
+
+const container=document.querySelector('#game');
+const scene=new THREE.Scene();scene.background=new THREE.Color(0x9aafaa);scene.fog=new THREE.FogExp2(0x9aafaa,.009);
+const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,240);
+const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;container.appendChild(renderer.domElement);
+scene.add(new THREE.HemisphereLight(0xd8e7dc,0x344338,2.1));const sun=new THREE.DirectionalLight(0xffe0b0,3.2);sun.position.set(-32,48,22);sun.castShadow=true;sun.shadow.mapSize.set(1536,1536);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;sun.shadow.bias=-.00015;scene.add(sun);
+const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
+const mats={grass:mat(0x5d7158),stone:mat(0x777b69),path:mat(0x9a8b70),dark:mat(0x25332d),uniform:mat(0x65745b),cloth:mat(0x758264),skin:mat(0xc69b75),metal:mat(0x727d73,.38,.55),beacon:mat(0xdac27d,.28,.35),wood:mat(0x69543e),roof:mat(0x4c4840),wall:mat(0xb7aa8a),leaf:mat(0x52654d)};
+function groundY(x,z){return .35*Math.sin(x*.15+z*.08)+.48*Math.sin(z*.105)+.25*Math.cos(x*.22)+.12*Math.sin(z*.31+x*.1)}
+// A rolling, walkable mountain valley.
+const N=120,span=120,positions=[],colors=[],indices=[];for(let iz=0;iz<=N;iz++)for(let ix=0;ix<=N;ix++){const x=(ix/N-.5)*span,z=(iz/N-.5)*span,y=groundY(x,z);positions.push(x,y,z);let c=new THREE.Color().setHSL(.255+Math.sin(x*.13+z*.1)*.012,.21,.34+Math.sin(z*.12+x*.06)*.025);colors.push(c.r,c.g,c.b);if(ix<N&&iz<N){const a=iz*(N+1)+ix,b=a+1,c0=a+N+1,d=c0+1;indices.push(a,c0,b,b,c0,d)}}
+const terrainGeo=new THREE.BufferGeometry();terrainGeo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));terrainGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));terrainGeo.setIndex(indices);terrainGeo.computeVertexNormals();const terrain=new THREE.Mesh(terrainGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));terrain.receiveShadow=true;scene.add(terrain);
+// Winding pale dirt trail.
+const pathVerts=[],pathIdx=[];for(let i=0;i<=150;i++){const t=i/150,z=49-t*103,x=Math.sin(z*.047)*6.8,w=2.1+Math.sin(t*18)*.22;for(const side of [-1,1])pathVerts.push(x+side*w,groundY(x+side*w,z)+.035,z)}for(let i=0;i<150;i++){const a=i*2;pathIdx.push(a,a+2,a+1,a+1,a+2,a+3)}const pg=new THREE.BufferGeometry();pg.setAttribute('position',new THREE.Float32BufferAttribute(pathVerts,3));pg.setIndex(pathIdx);pg.computeVertexNormals();const trail=new THREE.Mesh(pg,new THREE.MeshStandardMaterial({color:0x9b8c70,roughness:1,side:THREE.DoubleSide}));trail.receiveShadow=true;scene.add(trail);
+// Distant ridges, softly layered against the sky.
+for(let row=0;row<3;row++){for(let i=0;i<16;i++){const x=(i-7.5)*15+(row%2)*6,z=-64-row*17,h=16+Math.random()*18-row*2,r=11+Math.random()*7;const ridge=new THREE.Mesh(new THREE.ConeGeometry(r,h,6),mat(row===0?0x72827a:row===1?0x75847b:0x819087));ridge.position.set(x,h*.36,z);ridge.rotation.y=Math.random()*1;scene.add(ridge)}}
+// Rocks and small pines frame the path.
+const rng=(n)=>{let x=Math.sin(n*127.1+8.7)*43758.5453;return x-Math.floor(x)};
+for(let i=0;i<115;i++){let z=48-rng(i+2)*105,x=(rng(i+154)-.5)*47;if(Math.abs(x-Math.sin(z*.047)*6.8)<4)continue;const y=groundY(x,z);if(rng(i+319)>.43){const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.25,1.4,5),mats.wood);trunk.position.set(x,y+.7,z);trunk.castShadow=true;scene.add(trunk);for(let k=0;k<3;k++){const pine=new THREE.Mesh(new THREE.ConeGeometry(1.05-k*.16,2.3,6),mats.leaf);pine.position.set(x,y+1.6+k*.78,z);pine.castShadow=true;scene.add(pine)}}else{const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.45+rng(i+400)*.75,0),mats.stone);rock.position.set(x,y+.3,z);rock.scale.y=.7;rock.rotation.set(rng(i+500),rng(i+600),rng(i+700));rock.castShadow=true;rock.receiveShadow=true;scene.add(rock)}}
+// Old village at the far end of the valley.
+function house(x,z,s=1){const y=groundY(x,z);const body=new THREE.Mesh(new THREE.BoxGeometry(4*s,2.5*s,3.5*s),mats.wall);body.position.set(x,y+1.25*s,z);body.castShadow=true;body.receiveShadow=true;scene.add(body);const roof=new THREE.Mesh(new THREE.ConeGeometry(3.2*s,1.7*s,4),mats.roof);roof.position.set(x,y+3.1*s,z);roof.rotation.y=Math.PI/4;roof.castShadow=true;scene.add(roof);const door=new THREE.Mesh(new THREE.BoxGeometry(.8*s,1.5*s,.1),mats.wood);door.position.set(x+.7*s,y+.75*s,z+1.76*s);scene.add(door);const windowmat=mat(0x273b3b,.3);for(const dx of [-1.1,1.1]){const win=new THREE.Mesh(new THREE.BoxGeometry(.58*s,.55*s,.08),windowmat);win.position.set(x+dx*s,y+1.55*s,z+1.79*s);scene.add(win)}}
+house(-7,-47,1.1);house(0,-53,.85);house(8,-46,1.2);house(-15,-53,.72);house(15,-55,.8);
+// Simple Azerbaijan flag at the destination.
+function makeFlag(x,y,z,scale=1){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.055,.075,4.7,8),mats.metal);pole.position.set(x,y+2.35,z);pole.castShadow=true;scene.add(pole);const canvas=document.createElement('canvas');canvas.width=300;canvas.height=180;const ctx=canvas.getContext('2d');ctx.fillStyle='#00a3dd';ctx.fillRect(0,0,300,60);ctx.fillStyle='#ed2939';ctx.fillRect(0,60,300,60);ctx.fillStyle='#3f9c35';ctx.fillRect(0,120,300,60);ctx.fillStyle='white';ctx.beginPath();ctx.arc(136,90,20,0,Math.PI*2);ctx.fill();ctx.globalCompositeOperation='destination-out';ctx.beginPath();ctx.arc(143,90,16,0,Math.PI*2);ctx.fill();ctx.globalCompositeOperation='source-over';ctx.fillStyle='white';ctx.font='bold 33px serif';ctx.fillText('★',157,101);const flag=new THREE.Mesh(new THREE.PlaneGeometry(2.4*scale,1.42*scale,12,5),new THREE.MeshStandardMaterial({map:new THREE.CanvasTexture(canvas),side:THREE.DoubleSide,roughness:.7}));flag.position.set(x+1.22*scale,y+3.7*scale,z);flag.castShadow=true;flag.userData.flag=true;scene.add(flag);return flag}const finalFlag=makeFlag(1,groundY(1,-48),-48,1.05);
+// Player model: a readable, stylized field uniform and pack.
+const player=new THREE.Group();scene.add(player);function addPart(parent,geo,material,x,y,z){const mesh=new THREE.Mesh(geo,material);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh}
+addPart(player,new THREE.CapsuleGeometry(.37,.72,4,8),mats.uniform,0,1.1,0);addPart(player,new THREE.SphereGeometry(.31,10,8),mats.skin,0,1.86,0);addPart(player,new THREE.SphereGeometry(.34,10,8),mats.uniform,0,2.02,0);addPart(player,new THREE.BoxGeometry(.58,.14,.53),mats.dark,0,2.1,0);addPart(player,new THREE.BoxGeometry(.48,.57,.23),mats.dark,0,.98,.39);addPart(player,new THREE.BoxGeometry(.12,.38,.1),mat(0x00a3dd),-.18,1.24,.386);addPart(player,new THREE.BoxGeometry(.12,.38,.1),mat(0xed2939),-.06,1.24,.386);addPart(player,new THREE.BoxGeometry(.12,.38,.1),mat(0x3f9c35),.06,1.24,.386);const limbs=[];for(const side of [-1,1]){const arm=addPart(player,new THREE.CapsuleGeometry(.12,.48,3,6),mats.cloth,side*.44,1.22,0);arm.rotation.z=side*-.12;const leg=addPart(player,new THREE.CapsuleGeometry(.15,.55,3,6),mats.dark,side*.19,.39,0);limbs.push(leg)}
+player.position.set(Math.sin(39*.047)*6.8,groundY(Math.sin(39*.047)*6.8,39),39);let lastSafe=player.position.clone();
+
 </body></html>
