player.position.set(Math.sin(39*.047)*6.8,groundY(Math.sin(39*.047)*6.8,39),39);let lastSafe=player.position.clone();
// Three signal stations rise above the path and pulse when nearby.
const stations=[{z:19,x:Math.sin(19*.047)*6.8+3},{z:-7,x:Math.sin(-7*.047)*6.8-3},{z:-31,x:Math.sin(-31*.047)*6.8+2}].map((p,i)=>{const y=groundY(p.x,p.z);const group=new THREE.Group();group.position.set(p.x,y,p.z);scene.add(group);const base=addPart(group,new THREE.CylinderGeometry(.56,.72,.24,12),mats.stone,0,.12,0);const post=addPart(group,new THREE.CylinderGeometry(.14,.2,1.55,8),mats.metal,0,.95,0);const orb=addPart(group,new THREE.SphereGeometry(.35,16,12),new THREE.MeshStandardMaterial({color:0xe9c878,emissive:0xd9a94f,emissiveIntensity:2.5,roughness:.3}),0,1.9,0);const halo=new THREE.Mesh(new THREE.TorusGeometry(1.05,.045,8,36),new THREE.MeshBasicMaterial({color:0xf0cd75,transparent:true,opacity:.8}));halo.rotation.x=Math.PI/2;halo.position.y=.36;group.add(halo);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.09,.8,4,16,1,true),new THREE.MeshBasicMaterial({color:0xf0ce7d,transparent:true,opacity:.09,side:THREE.DoubleSide,depthWrite:false}));beam.position.y=2.3;group.add(beam);return {group,orb,halo,beam,active:false,index:i+1}});
// Quiet, floating search-lights; avoid their amber sweep and keep moving.
const drones=[];for(let i=0;i<3;i++){const z=[8,-19,-40][i],x=Math.sin(z*.047)*6.8+(i%2?3:-3),g=new THREE.Group();g.position.set(x,groundY(x,z)+3.6,z);scene.add(g);const shell=addPart(g,new THREE.OctahedronGeometry(.48,1),mat(0x5b6258,.4,.35),0,0,0);const eye=addPart(g,new THREE.SphereGeometry(.11,10,8),new THREE.MeshBasicMaterial({color:0xffa45b}),0,-.08,.41);const ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.035,6,24),new THREE.MeshBasicMaterial({color:0xf0b462,transparent:true,opacity:.6}));ring.rotation.x=Math.PI/2;g.add(ring);const beam=new THREE.Mesh(new THREE.ConeGeometry(1.45,5.5,18,1,true),new THREE.MeshBasicMaterial({color:0xf2bd74,transparent:true,opacity:.055,side:THREE.DoubleSide,depthWrite:false}));beam.position.y=-2.85;beam.rotation.x=Math.PI;g.add(beam);drones.push({g,z,x,phase:i*2.1,beam})}
// Floating specks catch the low evening light.
const dustGeo=new THREE.BufferGeometry(),dustPos=[];for(let i=0;i<190;i++)dustPos.push((Math.random()-.5)*68,Math.random()*12,(Math.random()-.5)*100);dustGeo.setAttribute('position',new THREE.Float32BufferAttribute(dustPos,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0xf4dca6,size:.075,transparent:true,opacity:.38}));scene.add(dust);
const keys={};let active=false,won=false,runHeld=false,stick={x:0,y:0},joystickTouch=null,shield=0,clock=new THREE.Clock(),toastTimer=0,soundOn=false,ac=null;
const $=s=>document.querySelector(s),beaconCount=$('#beacon-count'),barSpans=[...document.querySelectorAll('.progress span')];
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function updateObjective(){const n=stations.filter(s=>s.active).length;beaconCount.textContent=`${n} / 3`;barSpans.forEach((s,i)=>s.classList.toggle('done',i<n));if(n===3){$('#mission-title').textContent='The village is in sight';$('#mission-copy').textContent='Follow the ridge trail to the hilltop and raise the flag.'}else{$('#mission-title').textContent='Restore the signal';$('#mission-copy').textContent=`Find the ${3-n} remaining beacon${3-n===1?'':'s'} across the valley. Keep to the high ground.`}}
function activateNearest(){if(!active||won)return;const s=stations.find(s=>!s.active&&player.position.distanceTo(s.group.position)<3.4);if(s){s.active=true;s.orb.material.color.set(0x8fe0aa);s.orb.material.emissive.set(0x4ab878);s.halo.material.color.set(0x8fe0aa);s.beam.material.color.set(0x8fe0aa);lastSafe.copy(player.position);showToast(`Beacon ${s.index} restored · signal carried`);updateObjective();beep(540,.18)}else{const d=player.position.distanceTo(finalFlag.position);if(stations.every(s=>s.active)&&d<5){won=true;$('#ending').classList.remove('hidden');beep(760,.5)}else showToast(stations.every(s=>s.active)?'The village flag is just ahead':'Move closer to a beacon')}}
function beep(freq,duration){if(!soundOn)return;try{ac=ac||new AudioContext();const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.055,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch{}}
$('#start').addEventListener('click',()=>{active=true;$('#intro').classList.add('hidden');beep(440,.13)});$('#again').addEventListener('click',()=>location.reload());$('#interact').addEventListener('click',activateNearest);$('#sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';if(soundOn)beep(500,.1)});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyE'||e.code==='Space')activateNearest()});window.addEventListener('keyup',e=>keys[e.code]=false);$('#run').addEventListener('pointerdown',e=>{e.preventDefault();runHeld=true});for(const ev of ['pointerup','pointercancel','pointerleave'])$('#run').addEventListener(ev,()=>runHeld=false);
const pad=$('#stick'),knob=$('#knob');pad.addEventListener('pointerdown',e=>{joystickTouch=e.pointerId;pad.setPointerCapture(e.pointerId);moveStick(e)});pad.addEventListener('pointermove',e=>{if(e.pointerId===joystickTouch)moveStick(e)});for(const ev of ['pointerup','pointercancel'])pad.addEventListener(ev,e=>{if(e.pointerId===joystickTouch){joystickTouch=null;stick={x:0,y:0};knob.style.transform='translate(0px,0px)'}});function moveStick(e){const r=pad.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=43,m=Math.min(len,max);stick={x:len?dx/len*m/max:0,y:len?dy/len*m/max:0};knob.style.transform=`translate(${stick.x*m}px,${stick.y*m}px)`}
const camOffset=new THREE.Vector3(0,7.2,11.5),lookTarget=new THREE.Vector3();let walkTime=0;
function resetOnDetection(){shield=2.7;player.position.copy(lastSafe);$('#damage').classList.add('hit');setTimeout(()=>$('#damage').classList.remove('hit'),220);showToast('Searchlight spotted you · regrouping at the last signal');beep(170,.35)}
function update(dt,time){if(!active)return;const forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-stick.y;const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+stick.x;const len=Math.hypot(forward,side);const moving=len>.08;const isRun=keys.ShiftLeft||keys.ShiftRight||runHeld;const speed=isRun?8.3:5.1;if(moving&&!won){const f=forward/len,s=side/len;player.position.z-=f*speed*dt;player.position.x+=s*speed*dt;player.position.x=THREE.MathUtils.clamp(player.position.x,-23,23);player.position.z=THREE.MathUtils.clamp(player.position.z,-56,53);player.position.y=groundY(player.position.x,player.position.z);player.rotation.y=Math.atan2(s,-f);walkTime+=dt*speed*1.7;limbs.forEach((l,i)=>l.rotation.x=Math.sin(walkTime+i*Math.PI)*.45)}else limbs.forEach(l=>l.rotation.x*=.8);
// Hints and proximity interaction.
const near=stations.find(s=>!s.active&&player.position.distanceTo(s.group.position)<3.4);if(near){$('#hint').innerHTML='<b>E</b> activate beacon &nbsp;·&nbsp; follow the trail';$('#interact').style.opacity='1';$('#interact').textContent='ACTIVATE'}else if(stations.every(s=>s.active)&&player.position.distanceTo(finalFlag.position)<5){$('#hint').innerHTML='<b>E</b> raise the flag';$('#interact').style.opacity='1';$('#interact').textContent='RAISE'}else{$('#hint').innerHTML='<b>W A S D</b> move &nbsp;·&nbsp; <b>SHIFT</b> run &nbsp;·&nbsp; Reach the glowing beacons';$('#interact').style.opacity='.65';$('#interact').textContent='ACTIVATE'}
for(const s of stations){const pulse=1+Math.sin(time*2.5+s.index)*.08;s.orb.scale.setScalar(pulse);s.halo.rotation.z=time*.32;s.beam.material.opacity=s.active?.14:.055}
for(const d of drones){d.g.position.x=d.x+Math.sin(time*.56+d.phase)*2.1;d.g.position.y=groundY(d.g.position.x,d.z)+3.7+Math.sin(time*1.5+d.phase)*.24;d.g.rotation.y=time*.48+d.phase;d.beam.rotation.z=Math.sin(time*.8+d.phase)*.27;if(shield<=0&&player.position.distanceTo(d.g.position)<2.05)resetOnDetection()}
if(shield>0)shield-=dt;const desired=camera.position.clone().lerp(player.position.clone().add(camOffset),1-Math.pow(.001,dt));camera.position.copy(desired);lookTarget.set(player.position.x,player.position.y+1.1,player.position.z-3.1);camera.lookAt(lookTarget);
// Keep the destination flag cloth gently moving.
if(finalFlag.userData.flag)finalFlag.userData.flag.rotation.y=Math.sin(time*1.5)*.045;
}
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.035),time=clock.elapsedTime;update(dt,time);dust.rotation.y=time*.008;renderer.render(scene,camera)}frame();
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))}window.addEventListener('resize',resize);
</script>

