const $=s=>document.querySelector(s),beaconCount=$('#beacon-count'),barSpans=[...document.querySelectorAll('.progress span')];let active=false,won=false,shield=0,clock=new THREE.Clock(),toastTimer=0,soundOn=false,ac=null,walkTime=0,jumpV=0,onGround=true,crouched=false,keys={},stick={x:0,y:0},joystickTouch=null,runHeld=false;const camOffset=new THREE.Vector3(0,7.2,11.5),lookTarget=new THREE.Vector3();
function beep(freq,duration){if(!soundOn)return;try{ac=ac||new AudioContext();const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.055,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch{}}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
