function activateNearest(){if(!active||won)return;const s=stations.find(s=>!s.active&&player.position.distanceTo(s.group.position)<3.5);if(s){s.active=true;s.orb.material.color.set(0x8fe0aa);s.orb.material.emissive.set(0x4ab878);s.halo.material.color.set(0x8fe0aa);lastSafe.copy(player.position);showToast(`Beacon ${s.index} restored · signal carried`);updateObjective();beep(540,.18)}else if(stations.every(s=>s.active)&&player.position.distanceTo(new THREE.Vector3(1,groundY(1,-48)+3.7,-48))<5){won=true;$('#ending').classList.remove('hidden');beep(760,.5)}else showToast(stations.every(s=>s.active)?'The village flag is just ahead':'Move closer to a beacon')}
function refreshWeapon(){const w=weaponDefs[weaponIndex];$('#weapon-hud').innerHTML=`${w.name} <strong>${ammo[weaponIndex]} / ${reserve[weaponIndex]}${reloading?' · ...':''}</strong>`;guns.forEach((g,i)=>g.visible=i===weaponIndex)}
function selectWeapon(i){weaponIndex=(i+weaponDefs.length)%weaponDefs.length;refreshWeapon();beep(310+weaponIndex*70,.08)}function reload(){if(!active||reloading||ammo[weaponIndex]===weaponDefs[weaponIndex].mag||reserve[weaponIndex]<=0)return;reloading=true;refreshWeapon();showToast('Changing magazine');setTimeout(()=>{const w=weaponDefs[weaponIndex],need=w.mag-ammo[weaponIndex],take=Math.min(need,reserve[weaponIndex]);ammo[weaponIndex]+=take;reserve[weaponIndex]-=take;reloading=false;refreshWeapon();beep(240,.12)},weaponIndex===1?1500:1150)}
const raycaster=new THREE.Raycaster();function shoot(){if(!active||won||reloading||fireTimer>0)return;if(ammo[weaponIndex]<=0){showToast('Empty · reload');beep(120,.08);fireTimer=.25;return}const w=weaponDefs[weaponIndex];ammo[weaponIndex]--;refreshWeapon();fireTimer=w.rate;gunRoot.position.z=.12;setTimeout(()=>gunRoot.position.z=0,65);const dir=new THREE.Vector3(0,.1,-1).applyAxisAngle(new THREE.Vector3(0,1,0),player.rotation.y).normalize(),origin=player.position.clone().add(new THREE.Vector3(0,crouched?1.15:1.75,0));raycaster.set(origin,dir);raycaster.far=weaponIndex===1?35:25;let hitDrone=null,hitPoint=origin.clone().addScaledVector(dir,raycaster.far);for(const d of drones){if(d.disabled>0)continue;const hits=raycaster.intersectObjects(d.g.children,true);if(hits.length&&hits[0].distance<raycaster.far){raycaster.far=hits[0].distance;hitDrone=d;hitPoint=hits[0].point}}const geometry=new THREE.BufferGeometry().setFromPoints([origin,hitPoint]);const line=new THREE.Line(geometry,new THREE.LineBasicMaterial({color:weaponIndex===1?0xffbe6e:0xffe6aa,transparent:true,opacity:.88}));scene.add(line);setTimeout(()=>{scene.remove(line);geometry.dispose()},75);if(hitDrone){hitDrone.hp-=weaponIndex===1?3:1;hitDrone.g.scale.setScalar(.85);setTimeout(()=>hitDrone.g.scale.setScalar(1),100);if(hitDrone.hp<=0){hitDrone.disabled=9;hitDrone.g.visible=false;showToast('Watch drone disabled · route clear');beep(210,.24)}else beep(340,.06)}else beep(weaponIndex===1?100:180,.035)}
